## Code Example
```javascript
function minPostOffice(X, k) {
  const n = X.length;
  const cost = Array.from({length: n}, () => Array(n).fill(0));

  // Precompute prefix sums for O(1) range sum queries
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + X[i];
  }

  // Precompute block costs using median property
  for (let l = 0; l < n; l++) {
    for (let r = l; r < n; r++) {
      const m = Math.floor((l + r) / 2);
      cost[l][r] = (X[m] * (m - l) - (prefix[m] - prefix[l])) +
                   ((prefix[r + 1] - prefix[m + 1]) - X[m] * (r - m));
    }
  }

  // DP table and backpointers
  const dp = Array.from({length: n + 1}, () => Array(k + 1).fill(Infinity));
  const parent = Array.from({length: n + 1}, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let p = 1; p <= k; p++) {
    for (let i = 1; i <= n; i++) {
      for (let j = p - 1; j < i; j++) {
        const candidate = dp[j][p - 1] + cost[j][i - 1];
        if (candidate < dp[i][p]) {
          dp[i][p] = candidate;
          parent[i][p] = j;
        }
      }
    }
  }

  // Reconstruct solution
  const blocks = [];
  let curr = n;
  for (let p = k; p >= 1; p--) {
    const start = parent[curr][p];
    blocks.unshift([start, curr - 1]);
    curr = start;
  }

  return { cost: dp[n][k], blocks };
}
```

## Complexity Analysis
- Time: O(kn²) for DP transitions plus O(n²) for cost preprocessing
- Space: O(nk) for DP table, reducible to O(n) with layer optimization

## Why This Is Asked

Tests DP on strings, palindrome precomputation, and reconstruction. It also requires handling a non-trivial scoring function beyond simple lengths.

## Key Concepts

- Palindrome table isPal[i][j] for substring s[i..j]
- dist[i][j] stores number of distinct characters in s[i..j]
- DP state dp[i][t]: best score for first i chars partitioned into t palindromes
- Transition: for all j < i with isPal[j][i-1], dp[i][t] = max(dp[i][t], dp[j][t-1] + dist[j][i-1])
- Reconstruction via parent pointers to recover cut positions
- Time/space: O(n^2 k) time and O(n^2 k) space

## Code Example

```javascript
function maxPalPartitionScore(s, k) {
  const n = s.length;
  const isPal = Array.from({length: n}, () => Array(n).fill(false));
  const dist = Array.from({length: n}, () => Array(n).fill(0));

  for (let i = 0; i < n; i++) { isPal[i][i] = true; dist[i][i] = 1; }
  for (let len = 2; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1;
      if (s[i] === s[j] && (len === 2 || isPal[i+1][j-1])) isPal[i][j] = true;
      const seen = new Set();
      for (let p = i; p <= j; p++) seen.add(s[p]);
      dist[i][j] = seen.size;
    }
  }

  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-Infinity));
  const par = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= Math.min(i, k); t++) {
      for (let j = 0; j < i; j++) {
        if (isPal[j][i-1] && dp[j][t-1] > -Infinity) {
          const cand = dp[j][t-1] + dist[j][i-1];
          if (cand > dp[i][t]) { dp[i][t] = cand; par[i][t] = j; }
        }
      }
    }
  }

  // reconstruct cuts
  const cuts = [];
  let i = n, t = k;
  while (t > 0) {
    const j = par[i][t];
    cuts.push([j, i]);
    i = j; t--;
  }
  cuts.reverse();
  return { score: dp[n][k], cuts };
}
```

